      "required": ["id", "feature_package_id", "parent_feature", "title", "owners", "tags", "related_nodes", "workstream_kind", "build_target_kind", "phase_ref", "depends_on", "write_scope", "deploy_unit", "source_lineage", "classification", "tracker_binding_intent", "github_publication", "pr_completion_policy", "branch_policy", "acceptance", "verification", "rollback", "implementation_readiness", "graph_node_registration"],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^SYS-[A-Z0-9][A-Z0-9-]*$",
          "description": "task-spec id。dev-graph の graph_node_id 割当規約への接続は dev-graph-registration-contract.json と schemas-draft/dev-graph-registration.schema.json の確定契約に従う"
        },
        "feature_package_id": {"type": "string", "pattern": "^feature-package/[A-Za-z0-9._/-]+$"},
        "parent_feature": {"type": "string", "minLength": 1},
        "title": {"type": "string", "minLength": 1},
        "owners": {"type": "array", "items": {"type": "string", "minLength": 1}},
        "tags": {"type": "array", "uniqueItems": true, "items": {"type": "string", "minLength": 1}},
        "related_nodes": {"type": "array", "uniqueItems": true, "items": {"type": "string", "minLength": 1}},
        "workstream_kind": {
          "type": "string",
          "enum": ["frontend", "backend", "api", "data", "infrastructure", "security", "quality", "documentation", "operations"],
          "description": "生成対象タスクの主分類軸 (9値)。component-inventory.json の component_kind とは別軸"
        },
        "secondary_workstreams": {
          "type": "array",
          "items": {"type": "string", "enum": ["frontend", "backend", "api", "data", "infrastructure", "security", "quality", "documentation", "operations"]},
          "uniqueItems": true,
          "description": "主分類 workstream_kind 以外に副次的に関与する workstream (optional)。契約文書の secondary workstreams 句の受け皿"
        },
        "build_target_kind": {
          "type": "string",
          "enum": ["skill", "sub-agent", "slash-command", "hook", "script", "application-code"],
          "description": "ビルド対象語彙 (6値=component_kind5値+application-code)。component_kind 5値のときは plugin-dev-planner 同型 builder routing、application-code のときは task-graph build/capability-build へ汎用 handoff"
        },
        "phase_ref": {
          "type": "string",
          "pattern": "^P(0[1-9]|1[0-3])$",
          "description": "13 taskの一意なphase slot。P01..P13を各1件、配列順も同順で持つ"
        },
        "depends_on": {
          "type": "array",
          "items": {"type": "string"},
          "description": "task-graph 射影の入力となる依存 task id 配列"
        },
        "implementation_readiness": {
          "type": "object",
          "required": ["status", "missing_sections", "checked_at"],
          "properties": {
            "status": {"type": "string", "enum": ["complete", "incomplete"]},
            "missing_sections": {"type": "array", "items": {"type": "string"}, "uniqueItems": true},
            "checked_at": {"type": "string", "format": "date-time"}
          },
          "additionalProperties": false,
          "description": "C08 (check-implementation-readiness.py) 判定結果。complete 未達では実装 handoff を fail-closed で停止する (goal-spec C4/constraints)"
        },
        "write_scope": {"type": "array", "minItems": 1, "items": {"type": "string", "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"}},
        "deploy_unit": {"type": "string", "minLength": 1},
        "source_lineage": {"type": "array", "minItems": 1, "items": {"type": "string"}},
        "classification": {
          "type": "object",
          "additionalProperties": false,
          "required": ["confidence", "reason", "candidates"],
          "properties": {
            "confidence": {"type": "number", "minimum": 0, "maximum": 1},
            "reason": {"type": "string", "minLength": 1},
            "candidates": {
              "type": "array",
              "items": {
                "type": "object",
                "additionalProperties": false,
                "required": ["artifact_kind", "confidence", "candidate_path"],
                "properties": {
                  "artifact_kind": {"const": "task"},
                  "confidence": {"type": "number", "minimum": 0, "maximum": 1},
                  "candidate_path": {"type": "string", "pattern": "^tasks/.+\\.md$"}
                }
              }
            }
          }
        },
        "tracker_binding_intent": {
          "type": "string",
          "enum": ["auto", "beads", "github", "none"],
          "description": "spec側の明示intent。autoはdev-graph repo-configのexecution_tracker.modeで解決し、mode=bothでは禁止する。system-dev-plannerは宣言だけを行い、永続tracker_bindingへの解決と起票はdev-graphが所有する"
        },
        "github_publication": {
          "type": "object",
          "additionalProperties": false,
          "required": ["mode", "project_aliases", "labels", "milestone"],
          "properties": {"mode": {"enum": ["local_only", "issue", "issue_and_projects"]}, "project_aliases": {"type": "array", "uniqueItems": true, "items": {"type": "string", "minLength": 1}}, "labels": {"type": "array", "uniqueItems": true, "items": {"type": "string", "minLength": 1}}, "milestone": {"type": ["string", "null"]}},
          "description": "GitHubへの公開intent。tracker_binding_intent=beadsではlocal_only、githubではissue|issue_and_projectsを必須とする。beadsのGitHub viewer mirrorはbd github sync --push-onlyだけがauthorityで、Projects custom fieldsの管理対象外。"
        },
        "pr_completion_policy": {"enum": ["linked_pr_merged_all", "linked_pr_merged_any"]},
        "branch_policy": {
          "type": "object",
          "additionalProperties": false,
          "required": ["strategy", "worktree_lease_required", "completion_projection", "assignment_owner"],
          "properties": {"strategy": {"const": "one-task-one-branch"}, "worktree_lease_required": {"const": true}, "completion_projection": {"const": "default-branch-reconciliation"}, "assignment_owner": {"const": "dev-graph-scheduler"}}
        },
        "acceptance": {"type": "array", "minItems": 1, "items": {"type": "string"}},
        "verification": {"type": "array", "minItems": 1, "items": {"type": "string"}},
        "rollback": {"type": "string", "minLength": 1},
        "graph_node_registration": {
          "type": ["object", "null"],
          "properties": {
            "graph_node_id": {"type": ["string", "null"]},
            "file_path": {"type": ["string", "null"]},
            "parent_feature": {"type": ["string", "null"]},
            "feature_package_id": {"type": ["string", "null"]},
            "phase_ref": {"type": ["string", "null"]}
          },
          "additionalProperties": false,
          "description": "dev-graph の tasks/ グラフノード登録形式。実登録は dev-graph 側の所有 (本 plan は形式のみ提供)"
        }
      },
      "allOf": [
        {
          "if": {"required": ["tracker_binding_intent"], "properties": {"tracker_binding_intent": {"enum": ["beads", "none"]}}},
          "then": {"properties": {"github_publication": {"properties": {"mode": {"const": "local_only"}}}}}
        },
        {
          "if": {"required": ["tracker_binding_intent"], "properties": {"tracker_binding_intent": {"const": "github"}}},
          "then": {"properties": {"github_publication": {"properties": {"mode": {"enum": ["issue", "issue_and_projects"]}}}}}
        }
      ],
      "additionalProperties": false
    }
  }
}
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "system-build-handoff.schema.json",
  "title": "Versioned exact-13 system build handoff",
  "description": "C14 output. The handoff pins every source artifact and the pre-handoff manifest. To avoid a digest cycle, its own SHA-256 and the final manifest digest are stored only by staging-manifest.json; neither value is embedded here.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "kind",
    "identity",
    "source_inputs",
    "source_manifest",
    "digest_contract",
    "execution_tasks",
    "registration_request"
  ],
  "properties": {
    "schema_version": {
      "const": "1.0.0"
    },
    "kind": {
      "const": "system-build-handoff"
    },
    "identity": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "repository_id",
        "feature_id",
        "feature_package_id",
        "parent_feature",
        "source_feature_digest"
      ],
      "properties": {
        "repository_id": {
          "type": "string",
          "minLength": 1
        },
        "feature_id": {
          "type": "string",
          "minLength": 1,
          "description": "The invoking dev-graph feature id; C14 enforces equality with parent_feature."
        },
        "feature_package_id": {
          "type": "string",
          "pattern": "^feature-package/[A-Za-z0-9._/-]+$"
        },
        "parent_feature": {
          "type": "string",
          "minLength": 1
        },
        "source_feature_digest": {
          "type": "string",
          "pattern": "^sha256:[0-9a-f]{64}$"
        }
      }
    },
    "source_inputs": {
      "type": "array",
      "minItems": 16,
      "maxItems": 16,
      "uniqueItems": true,
      "description": "Exact ordered source set: package, inventory, graph, and P01..P13 task specs. The manifest is pinned separately as source_manifest.",
      "prefixItems": [
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "feature-package.json"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "workstream-inventory.json"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-graph.json"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-01-requirements.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-02-architecture.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-03-design-review.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-04-test-design.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-05-implementation.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-06-test-run.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-07-acceptance.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-08-refactoring-migration.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-09-quality-assurance.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-10-final-review.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-11-evidence.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-12-documentation-operations.md"}}}]},
        {"allOf": [{"$ref": "#/$defs/digested_path"}, {"properties": {"path": {"const": "task-specs/phase-13-release-deploy.md"}}}]}
      ],
      "items": false
    },
    "source_manifest": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "path",
        "sha256_before_handoff",
        "canonical_digest_before_handoff"
      ],
      "properties": {
        "path": {
          "const": "staging-manifest.json"
        },
        "sha256_before_handoff": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        },
        "canonical_digest_before_handoff": {
          "type": "string",
          "pattern": "^sha256:[0-9a-f]{64}$"
        }
      }
    },
    "digest_contract": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "algorithm",
        "source_digest_scope",
        "handoff_digest_location",
        "final_manifest_digest_scope",
        "self_reference_policy"
      ],
      "properties": {
        "algorithm": {"const": "sha256"},
        "source_digest_scope": {"const": "source_inputs only; handoff and manifest excluded"},
        "handoff_digest_location": {"const": "staging-manifest.json#files/system-build-handoff.json"},
        "final_manifest_digest_scope": {"const": "all manifest files including handoff; manifest itself excluded"},
        "self_reference_policy": {"const": "handoff omits its own digest and final manifest digest"}
      }
    },
    "execution_tasks": {
      "type": "array",
      "minItems": 13,
      "maxItems": 13,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["task_id", "phase_ref", "task_spec_path", "build_target_kind", "depends_on"],
        "properties": {
          "task_id": {"type": "string", "minLength": 1},
          "phase_ref": {"type": "string", "pattern": "^P(0[1-9]|1[0-3])$"},
          "task_spec_path": {"type": "string", "pattern": "^task-specs/phase-[0-9]{2}-[A-Za-z0-9-]+\\.md$"},
          "build_target_kind": {
            "enum": ["application-code", "skill", "sub-agent", "slash-command", "hook", "script", "documentation", "infrastructure", "data-migration"]
          },
          "depends_on": {
            "type": "array",
            "uniqueItems": true,
            "items": {"type": "string", "minLength": 1}
          }
        }
      }
    },
    "registration_request": {
      "type": "object",
      "additionalProperties": false,
      "required": ["path", "owner", "consumer", "status", "promotion_receipt", "registration_receipt"],
      "properties": {
        "path": {"const": "dev-graph-registration.json"},
        "owner": {"const": "system-dev-planner/C11"},
        "consumer": {"const": "dev-graph/C02"},
        "status": {"const": "deferred-until-promotion"},
        "promotion_receipt": {
          "allOf": [
            {"$ref": "#/$defs/deferred_receipt"},
            {"properties": {"path": {"const": "atomic-promotion-receipt.json"}, "owner": {"const": "system-dev-planner/C11"}}}
          ]
        },
        "registration_receipt": {
          "allOf": [
            {"$ref": "#/$defs/deferred_receipt"},
            {"properties": {"path": {"const": "dev-graph-registration-receipt.json"}, "owner": {"const": "dev-graph/C02"}}}
          ]
        }
      }
    }
  },
  "$defs": {
    "digested_path": {
      "type": "object",
      "additionalProperties": false,
      "required": ["path", "sha256"],
      "properties": {
        "path": {"type": "string", "minLength": 1},
        "sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$"}
      }
    },
    "deferred_receipt": {
      "type": "object",
      "additionalProperties": false,
      "required": ["path", "owner", "status", "produced_by_this_component"],
      "properties": {
        "path": {"type": "string", "minLength": 1},
        "owner": {"type": "string", "minLength": 1},
        "status": {"const": "not-emitted"},
        "produced_by_this_component": {"const": false}
      }
    }
  }
}
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "project-config.schema.json",
  "type": "object",
  "required": ["schema_version", "repository_id", "content_roots", "local_state", "path_policy", "plan_roots"],
  "$defs": {
    "relative_path": {"type": "string", "minLength": 1, "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$))(?![A-Za-z]:[\\\\/]).+$"}
  },
  "properties": {
    "schema_version": {"const": "1.0.0"},
    "repository_id": {
      "type": "string",
      "description": "C10 initがcanonical GitHub remoteまたはlocal git common-dirから導出して書込み、C09が再導出して照合するrepository identity。example/sentinel値の配置は禁止 (pattern不一致としてC09がexit 2で拒否する)",
      "pattern": "^(github:[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+|local:sha256:[0-9a-f]{64})$"
    },
    "content_roots": {
      "type": "object",
      "description": "dev-graph 基底 section (正本形=plugin-plans/dev-graph/templates/repo-config.example.json)。sdp は読取専用で既存値を上書きしない",
      "required": ["issues", "tasks", "specifications", "architecture", "documents", "system_spec"],
      "additionalProperties": {"$ref": "#/$defs/relative_path"}
    },
    "local_state": {
      "type": "object",
      "description": "dev-graph 基底 section。cache/locks は必須、graph 等の dev-graph 固有キーは共存を許容する",
      "required": ["cache", "locks"],
      "additionalProperties": {"$ref": "#/$defs/relative_path"}
    },
    "path_policy": {
      "type": "object",
      "description": "dev-graph 基底 section。caller-repository authority と repository 相対 path のみを固定する",
      "required": ["authority", "stored_paths", "allow_outside_repository", "follow_content_symlinks_outside_repository"],
      "properties": {
        "authority": {"const": "caller-repository"},
        "stored_paths": {"const": "repository-relative"},
        "allow_outside_repository": {"const": false},
        "follow_content_symlinks_outside_repository": {"const": false}
      },
      "additionalProperties": true
    },
    "plan_roots": {
      "type": "object",
      "description": "sdp 追加 section。C10 init が missing-key 追記 merge で非破壊追記する (既存値を上書きしない)",
      "required": ["staging", "published", "state"],
      "additionalProperties": {"$ref": "#/$defs/relative_path"}
    }
  },
  "additionalProperties": true
}

